global x y

x = 2*pi : -0.1 : -2*pi;
y = zeros(size(x));

apskaiciuoti_sin_x;
apskaiciuoti_vieneta;

figure; %[output:2963ca86]
plot(x, y, '--y*', 'LineWidth', 1.5, 'MarkerSize', 6); %[output:2963ca86]
title('Funkcijos y(x) grafikas'); %[output:2963ca86]
xlabel('x'); %[output:2963ca86]
ylabel('y'); %[output:2963ca86]
grid on; %[output:2963ca86]


